               peaks.get().size() == 2);
    TSM_ASSERT("The first peak should have a signal value of 7.",
               peaks.get()[0].getIntensity() == 7.);
    TSM_ASSERT("The second peak should have a signal value of 11.",
               peaks.get()[1].getIntensity() == 11.);
  }

